package net.schniedelsmp.smp.util;

import java.util.Locale;
import java.util.Map;

/** Sichere Auflösung kurzer IDs: Ein Präfix darf niemals zufällig den ersten Treffer wählen. */
public final class IdLookup {

    private IdLookup() {
    }

    public static <T> T uniquePrefix(Map<String, T> values, String input, int minimumPrefixLength) {
        if (values == null || input == null) return null;
        String normalized = input.trim().toLowerCase(Locale.ROOT);
        if (normalized.isEmpty()) return null;

        for (Map.Entry<String, T> entry : values.entrySet()) {
            if (entry.getKey().equalsIgnoreCase(normalized)) return entry.getValue();
        }
        if (normalized.length() < Math.max(1, minimumPrefixLength)) return null;

        T match = null;
        int matchingKeys = 0;
        for (Map.Entry<String, T> entry : values.entrySet()) {
            if (!entry.getKey().toLowerCase(Locale.ROOT).startsWith(normalized)) continue;
            if (++matchingKeys > 1) return null;
            match = entry.getValue();
        }
        return match;
    }
}

