package net.schniedelsmp.smp.util;

import org.junit.jupiter.api.Test;

import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class IdLookupTest {

    private final Map<String, String> values = new LinkedHashMap<>(Map.of(
            "abcd1234", "first",
            "abcd5678", "second",
            "ffff0000", "third"
    ));

    @Test
    void exactIdAlwaysWorks() {
        assertEquals("first", IdLookup.uniquePrefix(values, "ABCD1234", 4));
    }

    @Test
    void uniquePrefixWorksButAmbiguousPrefixDoesNot() {
        assertEquals("third", IdLookup.uniquePrefix(values, "ffff", 4));
        assertNull(IdLookup.uniquePrefix(values, "abcd", 4));
        assertNull(IdLookup.uniquePrefix(values, "fff", 4));
    }

    @Test
    void twoKeysSharingOneValueAreStillAmbiguous() {
        String shared = "same-object";
        Map<String, String> aliased = new LinkedHashMap<>();
        aliased.put("abcd1234", shared);
        aliased.put("abcd5678", shared);

        assertNull(IdLookup.uniquePrefix(aliased, "abcd", 4));
        assertEquals(shared, IdLookup.uniquePrefix(aliased, "abcd1234", 4));
        assertEquals(shared, IdLookup.uniquePrefix(aliased, "abcd5678", 4));
    }

    @Test
    void equalButDistinctValuesAreAmbiguous() {
        Map<String, String> equalValues = new LinkedHashMap<>();
        equalValues.put("abcd1234", new String("same"));
        equalValues.put("abcd5678", new String("same"));

        assertNull(IdLookup.uniquePrefix(equalValues, "abcd", 4));
    }
}

