        if (hasWord('test') || hasWord('spec') || hasWord('check'))
            return 'tests';
        if (hasWord('build') || hasWord('compile'))
            return 'build';
        if (hasWord('lint'))
            return 'typecheck';
        return null;
    }
    if (['cargo', 'go'].includes(prog))
        return hasWord('test') ? 'tests' : null;
    if (prog === 'npm' || prog === 'pnpm' || prog === 'yarn' || prog === 'bun') {
        if (rest.some((a) => /^(test|check)$/.test(a)))
            return 'tests';
        if (rest.some((a) => /^build$/.test(a)))
            return 'build';
        if (rest.some((a) => /^lint$/.test(a)))
            return 'typecheck';
        return null;
    }
    if (prog === 'python' || prog === 'python3' || prog === 'py') {
        if (hasWord('-m') && rest.includes('pytest'))
            return 'tests';
        if (hasWord('-m') && rest.includes('unittest'))
            return 'tests';
        return null;
    }
    if (prog === 'node')
        return null; // `node --test` is the native Node path
