        if (typeof raw.proofs !== 'object' || raw.proofs === null || Array.isArray(raw.proofs)) {
            return { manifest: null, problems: [`${UNIVERSAL_MANIFEST} "proofs" must be an object mapping a 64-hex requirement digest to a check name this manifest declares`] };
        }
        for (const [digest, name] of Object.entries(raw.proofs)) {
            if (!/^[0-9a-f]{64}$/.test(digest)) {
                problems.push(`${UNIVERSAL_MANIFEST} proofs["${digest}"]: the key must be a full 64-hex requirement digest (get it from: amabie task --requirement "<text>")`);
                continue;
            }
            if (typeof name !== 'string' || !declared.has(name)) {
                problems.push(`${UNIVERSAL_MANIFEST} proofs["${digest}"]: "${String(name)}" is not a check this manifest declares (${[...declared].sort().join(', ')})`);
                continue;
            }
            proofs[digest] = name;
        }
    }
    if (problems.length > 0)
        return { manifest: null, problems };
    return { manifest: { scopes: scopes.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0)), proofs }, problems: [] };
}
/** Does a NATIVE adapter discover checks in this directory? Used to DEFER: the
 *  universal door yields to a native adapter that is actually present. */
function nativeAdapterOwns(root, program) {
    try {
        if (['cargo', 'rustc'].includes(program))
            return has(root, 'Cargo.toml');
        if (['go', 'gofmt'].includes(program))
            return has(root, 'go.mod') || has(root, 'go.work');

